import{_ as s,a0 as a,w as r,s as p,I as l,x as e,a1 as i,A as o,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"为什么我喜欢将 KDE 作为我的 Linux 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"为什么我喜欢将 KDE 作为我的 Linux 桌面 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么我喜欢将 KDE 作为我的 Linux 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么我喜欢将 KDE 作为我的 Linux 桌面 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220221 Why I love KDE for my Linux desktop","title":"为什么我喜欢将 KDE 作为我的 Linux 桌面","tag":"202202","desc":""},"relativePath":"202202/20220221 Why I love KDE for my Linux desktop.md","filePath":"[post].md"}'),d={name:"202202/20220221 Why I love KDE for my Linux desktop.md"};function m(x,t,f,D,K,E){const n=a("Link");return r(),p("div",null,[t[22]||(t[22]=l("h1",{id:"为什么我喜欢将-kde-作为我的-linux-桌面",tabindex:"-1"},[e("为什么我喜欢将 KDE 作为我的 Linux 桌面 "),l("a",{class:"header-anchor",href:"#为什么我喜欢将-kde-作为我的-linux-桌面","aria-label":"Permalink to “为什么我喜欢将 KDE 作为我的 Linux 桌面”"},"​")],-1)),t[23]||(t[23]=l("blockquote",null,[l("p",null,"KDE Plasma 桌面的目标是整合、一致和定制的完美结合。")],-1)),t[24]||(t[24]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202202/27/161217bz1a9r1r9s1z11ns.jpg",alt:""})],-1)),l("p",null,[t[3]||(t[3]=e("开源引以为豪的事情之一是选择。你不必满足于你不喜欢的东西。你可以改变你的文件管理器、你的 ",-1)),i(n,{href:"https://opensource.com/article/21/2/open-source-text-editors"},{default:o(()=>[...t[0]||(t[0]=[e("文本编辑器",-1)])]),_:1}),t[4]||(t[4]=e("，你甚至有超过 ",-1)),i(n,{href:"https://opensource.com/article/20/5/linux-desktops"},{default:o(()=>[...t[1]||(t[1]=[e("24 个桌面",-1)])]),_:1}),t[5]||(t[5]=e(" 可以选择。和许多 Linux 用户一样，我一开始经常切换自己使用的桌面。最初我不知道自己喜欢什么，因为我还没有尝试过所有可用的东西。在 2008 年 1 月的一个好日子，KDE 4.0 发布了，从我看到 Plasma 桌面的那一刻起，我就知道这是我一直在等待的 Linux 桌面（那时我成为 Linux 用户才一年，我想我没必要等太久）。尽管我的笔记本上有 GNOME，我的树莓派上有 ",-1)),i(n,{href:"https://opensource.com/article/19/12/fluxbox-linux-desktop"},{default:o(()=>[...t[2]||(t[2]=[e("Fluxbox",-1)])]),_:1}),t[6]||(t[6]=e("，可能还有其他一些组合，但我认为自己是 Plasma 桌面的用户，也是 KDE 社区的一员。",-1))]),t[25]||(t[25]=u('<h3 id="我爱-kde-的三个理由" tabindex="-1">我爱 KDE 的三个理由 <a class="header-anchor" href="#我爱-kde-的三个理由" aria-label="Permalink to “我爱 KDE 的三个理由”">​</a></h3><p>爱上 KDE 的理由有很多，但这里有我的三个理由：</p><h4 id="一致性" tabindex="-1">一致性 <a class="header-anchor" href="#一致性" aria-label="Permalink to “一致性”">​</a></h4><p><img src="https://opensource.com/sites/default/files/kde-dolphin-nav.jpg" alt="Dolphin 文件管理器" title="Dolphin file manager"></p><p>一致性是教给用户一个新工具的重要部分。最理想的情况是，一个人在一个应用程序中学习了一些东西，然后在不知不觉中把同样的知识转移到另一个应用程序中。KDE 项目的目标是在其所有的应用程序中实现一致性，这也是 KDE 框架存在的原因之一。越多 KDE 开发者使用框架，用户需要学习的东西就越少，因为使用过一个应用程序的用户已经熟悉了该框架所提供的关键组件。</p><p>大量的代码在应用程序之间被重复使用。Konsole 可以作为 Dolphin 和 Kate 的一个面板启动。工具栏配置选项在所有应用程序中基本相同。有一些重要的惯例，比如用单次点击来打开一个文件或文件夹，而不是双击（你会节省几个微秒，相信我），以及可靠的右键菜单选项。</p><p>KDE 的伟大之处在于，当你想做一件你以前从未做过的事情时，你通常可以猜到你应该如何实现它。你被 KDE 的内部一致性所训练，知道应该怎么做。这并不总是有效的，毕竟你可能找错了地方，或者你可能试图让两种技术一起工作，而这两种技术没有过互相影响，但一般来说，你知道在哪里寻找一个选项，或者你知道在哪里拖动一个文件，或者何时右击一个对象，或者长按一个按钮。你通过实践来学习 KDE，那是一种很好的感觉。</p><h4 id="整合" tabindex="-1">整合 <a class="header-anchor" href="#整合" aria-label="Permalink to “整合”">​</a></h4><p><img src="https://opensource.com/sites/default/files/kde-gwenview-integration.jpg" alt="Gwenview 参考了 Krita" title="Gwenview referencing Krita"></p><p>KDE 项目被很多人称为桌面，但还有一群用户认为 KDE 更像是一套应用程序。他们都是正确的！</p><p>你可以运行 Plasma 桌面，也可以运行一个不同的桌面或窗口管理器，而只使用 KDE 应用程序。有很多东西可以选择，它们一起构成了一个完整的操作系统，影响了操作系统的风格倾向。当然，还有一些工作仍在进行中，但在我每天使用的应用程序中，有用于联系人、电子邮件和日历的 Kontact 套件，用于视频编辑的 Kdenlive，用于插图和摄影的 Krita，用于文件管理的 Dolphin，用于 RSS 订阅的 Akregator，用于存档的 Ark，用于终端的 Konsole，用于播放音乐的 Juk，用于从我的手机传输文件的 KDE Connect，这个名单还在继续增长。我并不是只安装 K 应用，因为在 KDE 开发之外也有很多伟大的应用程序，但是有这样一套完整的工具使用同一套框架和库是很好的。它提供了凝聚力，这使得整合成为可能。</p><h4 id="定制" tabindex="-1">定制 <a class="header-anchor" href="#定制" aria-label="Permalink to “定制”">​</a></h4><p><img src="https://opensource.com/sites/default/files/kde-settings-theme_0.jpg" alt="系统设置" title="System settings"></p><p>Plasma 桌面认识到，不同的用户对他们的工作空间有不同的要求和偏好。KDE 中几乎所有的东西都可以定制。你可以改变你的主题，你可以改变窗口装饰的布局，你可以改变打开一个文件所需的点击次数，什么是可点击的，什么是可拖动的，你可以在窗口内移动面板，然后当你不希望这些设置适用于某个应用程序时，你可以为它们设置特定的窗口覆盖项。</p><p>如果这听起来让人不知所措，也没错。但你不应该记住或甚至知道所有可能的定制。默认值是令人愉快的直观，而且大部分的行为是你期望的桌面行为。有一些小的 KDE 惯例你可能要习惯，但是当你发现你不喜欢的东西时，你知道因为它是 KDE，它可以被改变。你离开找到正确的旋钮或转盘来改变这个设置只距离一个参考文档。</p><h3 id="让-linux-kde-成为你自己的" tabindex="-1">让 Linux KDE 成为你自己的 <a class="header-anchor" href="#让-linux-kde-成为你自己的" aria-label="Permalink to “让 Linux KDE 成为你自己的”">​</a></h3><p>我配置 Plasma 桌面的方式与我在会议和工作中看到的其他桌面不同，它是我在生活中尝试过的所有桌面中最喜欢的古怪东西的综合体。而这正是 KDE 的特别之处。它能适应我的每一个奇思妙想，甚至是非理性的奇思妙想。下次你必须在桌面之间做出选择时，看看 KDE 吧。如果你不喜欢你所看到的，给它点时间。你要么学会爱上它（单击操作就很好，我发誓），要么你最终会改变它。无论哪种方式，你都赢了。</p><hr>',18)),l("p",null,[t[8]||(t[8]=e("via: ",-1)),i(n,{href:"https://opensource.com/article/22/2/why-i-love-linux-kde"},{default:o(()=>[...t[7]||(t[7]=[e("https://opensource.com/article/22/2/why-i-love-linux-kde",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/seth"},{default:o(()=>[...t[9]||(t[9]=[e("Seth Kenlon",-1)])]),_:1}),t[14]||(t[14]=e(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[10]||(t[10]=[e("lujun9972",-1)])]),_:1}),t[15]||(t[15]=e(" 译者：",-1)),i(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[11]||(t[11]=[e("wxy",-1)])]),_:1}),t[16]||(t[16]=e(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[19]||(t[19]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[17]||(t[17]=[e("LCTT",-1)])]),_:1}),t[20]||(t[20]=e(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:o(()=>[...t[18]||(t[18]=[e("Linux中国",-1)])]),_:1}),t[21]||(t[21]=e(" 荣誉推出",-1))])])}const g=s(d,[["render",m]]);export{L as __pageData,g as default};
